// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo, useId } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from areaMissing ----
/**
 * A daily closing-price series with three deliberate outage windows, so the
 * `.defined()` gaps in the area are actually visible.
 */
type MissingPoint = { date: Date; close: number | null };

/** Seeded LCG: the walk must be identical across hot reloads. */
function seededRandom(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1664525 + 1013904223) % 4294967296;
    return state / 4294967296;
  };
}

const DAYS = 182;
const GAPS: [number, number][] = [
  [31, 48],
  [92, 101],
  [138, 159]
];

const random = seededRandom(20240102);

let level = 168;

const priceSeries: MissingPoint[] = Array.from({ length: DAYS }, (_, i) => {
  level += (random() - 0.48) * 6 + Math.sin(i / 19) * 1.4;
  const isMissing = GAPS.some(([start, end]) => i >= start && i <= end);
  return {
    date: new Date(2024, 0, 2 + i),
    close: isMissing ? null : Math.round(level * 100) / 100
  };
});

const MARGIN = { top: 16, right: 20, bottom: 36, left: 52 };

/** A closing price per date; a null close is a gap the area breaks across. */
export type Data = { date: Date; close: number | null }[];

export default function AreaChartMissingData({ data = priceSeries, width }:
  { data?: Data; width: number }) {
  const gradientId = useId();
  const height = Math.round(width * 0.5);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleTime()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(data, (d) => d.close ?? 0) ?? 0])
        .nice()
        .range([innerHeight, 0]),
    [data, innerHeight]
  );

  const area = useMemo(
    () =>
      d3
        .area<Data[number]>()
        .defined((d) => d.close !== null)
        .x((d) => x(d.date))
        .y0(innerHeight)
        .y1((d) => y(d.close ?? 0))
        .curve(d3.curveMonotoneX),
    [x, y, innerHeight]
  );

  // Dropping the missing points entirely lets the same generator span the gaps,
  // which is what the interpolation would have looked like.
  const interpolatedPath = useMemo(
    () => area(data.filter((d) => d.close !== null)) ?? '',
    [area, data]
  );

  const observedPath = useMemo(() => area(data) ?? '', [area, data]);

  const xTicks: Tick[] = useMemo(
    () => x.ticks(6).map((v) => ({ value: d3.timeFormat('%b')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('$,.0f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Area chart of a daily closing price with gaps for missing data">
      <defs>
        <linearGradient id={gradientId} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0%" stopColor="var(--accent)" stopOpacity={0.65} />
          <stop offset="100%" stopColor="var(--accent)" stopOpacity={0.04} />
        </linearGradient>
      </defs>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        <path d={interpolatedPath} fill="var(--muted)" fillOpacity={0.22} />
        <path d={observedPath} fill={`url(#${gradientId})`} stroke="var(--accent)" strokeWidth={1.5} />
        <g transform="translate(8,6)" fontSize={11} fill="var(--muted)">
          <rect width={10} height={10} fill="var(--accent)" fillOpacity={0.6} />
          <text x={16} y={9}>observed</text>
          <rect y={16} width={10} height={10} fill="var(--muted)" fillOpacity={0.22} />
          <text x={16} y={25}>interpolated</text>
        </g>
      </g>
    </svg>
  );
}
